op();//this is used to remove the first read variable\n    }\n    data.push(temperature); //read variables and store in data\n\n    //Settings for the line graph title\n    auto header =  text(0, 0)\n                .value("Temperature Reading")\n                .align(center)\n                .color(TFT_WHITE)\n                .valign(vcenter)\n                .width(tft.width())\n                .thickness(2);\n\n    header.height(header.font_height() * 2);\n    header.draw(); //Header height is the twice the height of the font\n\n  //Settings for the line graph\n    auto content = line_chart(20, header.height()); //(x,y) where the line graph begins\n         content\n                .height(tft.height() - header.height() * 1.5) //actual height of the line chart\n                .width(tft.width() - content.x() * 2) //actual width of the line chart\n                .based_on(0.0) //Starting point of y-axis, must be a float\n                .show_circle(true) //drawing a cirle at each point, default is on.\n                .y_role_color(TFT_WHITE)\n                .x_role_color(TFT_WHITE)\n                .value(data) //passing through the data to line graph\n                .color(TFT_RED) //Setting the color for the line\n                .draw();\n\n    spr.pushSprite(0, 0);\n    delay(50);\n}\n'})}),"\n",(0,r.jsx)(n.h2,{id:"wio-terminal-com-grove---sensor-gps",children:"Wio Terminal com Grove - Sensor GPS"}),"\n",(0,r.jsx)(n.p,{children:"Esta se\xe7\xe3o apresenta como usar o Grove - GPS Sensor com o Wio Terminal para obter informa\xe7\xf5es de GPS em tempo real. O pr\xf3prio sensor gera dados de GPS NMEA que usaremos a biblioteca TinyGPSPlus para analisar e converter em informa\xe7\xf5es leg\xedveis."}),"\n",(0,r.jsx)(n.h3,{id:"instala\xe7\xe3o-das-bibliotecas-3",children:"Instala\xe7\xe3o das bibliotecas"}),"\n",(0,r.jsxs)(n.ol,{children:["\n",(0,r.jsxs)(n.li,{children:["Instale a ",(0,r.jsx)(n.a,{href:"https://github.com/mikalhart/TinyGPSPlus",children:"TinyG